"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
/**
 * Table sort menu component
 * @description A sort menu component for DataTable that allows users to manage multiple sorting criteria. Users can add, remove, and reorder sorting fields, as well as select sort directions.
 */

import type { ColumnSort, RowData } from "@tanstack/react-table"
import { ArrowDownUp, Trash2, CircleHelp } from "lucide-react"
import * as React from "react"

import { Badge } from "@/components/ui/badge"
import {
  Button,
  buttonVariants,
} from "@/components/niko-table/primitives/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/niko-table/primitives/command"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/niko-table/primitives/popover"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/niko-table/primitives/tooltip"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/niko-table/primitives/select"
import {
  Sortable,
  SortableContent,
  SortableItem,
  SortableItemHandle,
  SortableOverlay,
} from "@/components/ui/sortable"
import { useKeyboardShortcut } from "../hooks/use-keyboard-shortcut"
import { cn } from "@/lib/utils"
import { ChevronsUpDown, Grip } from "lucide-react"

// Import sort labels from TableColumnHeader for consistency
import { SORT_LABELS } from "../config/data-table"
import { FILTER_VARIANTS } from "../lib/constants"

import type { DataTableInstance } from "../types"
interface TableSortItemProps {
  sort: ColumnSort
  menuId: string
  columns: { id: string; label: string }[]
  columnLabels: Map<string, string>
  onSortUpdate: (sortId: string, updates: Partial<ColumnSort>) => void
  onSortRemove: (sortId: string) => void
  getVariantForColumn?: (id: string) => string | undefined
  className?: string
}

const getSortItemId = (menuId: string, sortId: string) =>
  `${menuId}-sort-${sortId}`

function TableSortItem({
  sort,
  menuId,
  columns,
  columnLabels,
  onSortUpdate,
  onSortRemove,
  getVariantForColumn,
}: TableSortItemProps) {
  const sortItemId = getSortItemId(menuId, sort.id)
  const fieldListboxId = `${sortItemId}-field-listbox`
  const fieldTriggerId = `${sortItemId}-field-trigger`
  const directionListboxId = `${sortItemId}-direction-listbox`

  const [showFieldSelector, setShowFieldSelector] = React.useState(false)
  const [showDirectionSelector, setShowDirectionSelector] =
    React.useState(false)

  const onItemKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (
        event.target instanceof HTMLInputElement ||
        event.target instanceof HTMLTextAreaElement
      ) {
        return
      }

      if (showFieldSelector || showDirectionSelector) {
        return
      }

      if (["backspace", "delete"].includes(event.key.toLowerCase())) {
        event.preventDefault()
        onSortRemove(sort.id)
      }
    },
    [sort.id, showFieldSelector, showDirectionSelector, onSortRemove],
  )

  const variant =
    (getVariantForColumn?.(sort.id) as keyof typeof SORT_LABELS | undefined) ??
    FILTER_VARIANTS.TEXT
  const labels = SORT_LABELS[variant] || SORT_LABELS[FILTER_VARIANTS.TEXT]

  return (
    // No `asChild`/`render`: the sortable's Base UI and React Aria builds
    // take `render`, the Radix build `asChild`, so the item stays its own div.
    <SortableItem
      value={sort.id}
      id={sortItemId}
      role="listitem"
      tabIndex={-1}
      className="flex items-center gap-2"
      onKeyDown={onItemKeyDown}
    >
      <Popover open={showFieldSelector} onOpenChange={setShowFieldSelector}>
        <PopoverTrigger asChild>
          <Button
            id={fieldTriggerId}
            aria-controls={fieldListboxId}
            variant="outline"
            className="w-44 justify-between rounded font-normal"
          >
            <span className="truncate">{columnLabels.get(sort.id)}</span>
            <ChevronsUpDown className="opacity-50" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          id={fieldListboxId}
          className="w-[var(--radix-popover-trigger-width,var(--anchor-width))] origin-[var(--radix-popover-content-transform-origin,var(--transform-origin))] p-0"
        >
          <Command>
            <CommandInput placeholder="Search fields..." />
            <CommandList>
              <CommandEmpty>No fields found.</CommandEmpty>
              <CommandGroup>
                {columns.map(column => (
                  <CommandItem
                    key={column.id}
                    value={column.id}
                    onSelect={value => {
                      onSortUpdate(sort.id, { id: value })
                      // The row is keyed by field, so it re-mounts: move
                      // focus to the new row's trigger, not the body.
                      requestAnimationFrame(() =>
                        document
                          .getElementById(
                            `${getSortItemId(menuId, value)}-field-trigger`,
                          )
                          ?.focus(),
                      )
                    }}
                  >
                    <span className="truncate">{column.label}</span>
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
      <Select
        open={showDirectionSelector}
        onOpenChange={setShowDirectionSelector}
        value={sort.desc ? "desc" : "asc"}
        // Spread so it type-checks against Radix too: Base UI reads the
        // closed trigger's label only from `items`, Radix ignores the prop.
        {...{ items: labels }}
        onValueChange={(value: string | null) =>
          // Base UI selects pass null on clear; Radix never does
          value && onSortUpdate(sort.id, { desc: value === "desc" })
        }
      >
        <SelectTrigger
          aria-controls={directionListboxId}
          className="h-8 w-24 rounded data-size:h-8"
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent
          id={directionListboxId}
          className="min-w-[var(--radix-select-trigger-width,var(--anchor-width))] origin-[var(--radix-select-content-transform-origin,var(--transform-origin))]"
        >
          <SelectItem value="asc">{labels.asc}</SelectItem>
          <SelectItem value="desc">{labels.desc}</SelectItem>
        </SelectContent>
      </Select>
      <Button
        aria-controls={sortItemId}
        variant="outline"
        size="icon"
        className="size-8 shrink-0 rounded"
        onClick={() => onSortRemove(sort.id)}
      >
        <Trash2 />
      </Button>
      <SortableItemHandle
        aria-controls={sortItemId}
        className={cn(
          buttonVariants({ variant: "outline", size: "icon" }),
          "size-8 shrink-0 rounded",
        )}
      >
        <Grip />
      </SortableItemHandle>
    </SortableItem>
  )
}

export interface TableSortMenuProps<
  TData extends RowData,
> extends React.ComponentProps<typeof PopoverContent> {
  table: DataTableInstance<TData>
  debounceMs?: number
  throttleMs?: number
  shallow?: boolean
  className?: string
  /**
   * Callback fired when sorting state changes
   * Useful for server-side sorting or external state management
   */
  onSortingChange?: (sorting: ColumnSort[]) => void
}

export function TableSortMenu<TData extends RowData>({
  table,
  onSortingChange: externalOnSortingChange,
  className,
  ...props
}: TableSortMenuProps<TData>) {
  const getVariantForColumn = React.useCallback(
    (id: string): string | undefined =>
      table.getAllColumns().find(c => c.id === id)?.columnDef?.meta?.variant,
    [table],
  )
  // ============================================================================
  // State & Refs
  // ============================================================================
  const id = React.useId()
  const labelId = React.useId()
  const descriptionId = React.useId()
  const [open, setOpen] = React.useState(false)
  const addButtonRef = React.useRef<HTMLButtonElement>(null)

  const sorting = table.state.sorting
  // Hide "Add sort" when adding a second entry would silently replace the
  // first (`enableMultiSort: false`). The first sort can still be added
  // from the menu when no sort exists yet.
  const canShowAddSort =
    table.options.enableMultiSort !== false || sorting.length === 0

  // ============================================================================
  // Sorting State Management
  // ============================================================================
  const onSortingChange = React.useCallback(
    (updater: React.SetStateAction<ColumnSort[]>) => {
      // Resolve the next sorting against the table's current state, not the
      // closure-captured `sorting` — eliminates any chance of drift if the
      // callback fires from an interaction queued before the latest render.
      const nextSorting =
        typeof updater === "function" ? updater(table.state.sorting) : updater
      table.setSorting(nextSorting)
      externalOnSortingChange?.(nextSorting)
    },
    [table, externalOnSortingChange],
  )

  // ============================================================================
  // Column Labels & Available Columns
  // ============================================================================
  const { columnLabels, columns } = React.useMemo(() => {
    const labels = new Map<string, string>()
    const sortingIds = new Set(sorting.map(s => s.id))
    const availableColumns: { id: string; label: string }[] = []

    for (const column of table.getAllColumns()) {
      if (!column.getCanSort()) continue

      const label = column.columnDef.meta?.label ?? column.id
      labels.set(column.id, label)

      if (!sortingIds.has(column.id)) {
        availableColumns.push({ id: column.id, label })
      }
    }

    return {
      columnLabels: labels,
      columns: availableColumns,
    }
    // Depend on the column set, not just the (stable) table ref.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sorting, table, table.options.columns])

  // ============================================================================
  // Sort Actions
  // ============================================================================
  const onSortAdd = React.useCallback(() => {
    const firstColumn = columns[0]
    if (!firstColumn) return

    onSortingChange(prevSorting => [
      ...prevSorting,
      { id: firstColumn.id, desc: false },
    ])
  }, [columns, onSortingChange])

  const onSortUpdate = React.useCallback(
    (sortId: string, updates: Partial<ColumnSort>) => {
      onSortingChange(prevSorting => {
        if (!prevSorting) return prevSorting
        return prevSorting.map(sort =>
          sort.id === sortId ? { ...sort, ...updates } : sort,
        )
      })
    },
    [onSortingChange],
  )

  const onSortRemove = React.useCallback(
    (sortId: string) => {
      onSortingChange(prevSorting =>
        prevSorting.filter(item => item.id !== sortId),
      )
    },
    [onSortingChange],
  )

  const onSortingReset = React.useCallback(
    () => onSortingChange(table.initialState.sorting),
    [onSortingChange, table.initialState.sorting],
  )

  // ============================================================================
  // Keyboard Shortcuts
  // ============================================================================
  // Toggle sort menu with 'S' key
  useKeyboardShortcut({
    key: "s",
    onTrigger: () => setOpen(prev => !prev),
  })

  // Reset sorting with Shift+S
  useKeyboardShortcut({
    key: "s",
    requireShift: true,
    onTrigger: () => onSortingReset(),
    condition: () => sorting.length > 0,
  })

  // Trigger button keyboard shortcuts (Backspace/Delete to reset)
  const onTriggerKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLButtonElement>) => {
      if (
        ["backspace", "delete"].includes(event.key.toLowerCase()) &&
        sorting.length > 0
      ) {
        event.preventDefault()
        onSortingReset()
      }
    },
    [sorting.length, onSortingReset],
  )

  // ============================================================================
  // Render
  // ============================================================================

  return (
    <Sortable
      value={sorting}
      onValueChange={onSortingChange}
      getItemValue={item => item.id}
    >
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            onKeyDown={onTriggerKeyDown}
            className={className}
          >
            <ArrowDownUp />
            Sort
            {sorting.length > 0 && (
              <Badge
                variant="secondary"
                className="h-[18.24px] rounded-[3.2px] px-[5.12px] font-mono text-[10.4px] font-normal"
              >
                {sorting.length}
              </Badge>
            )}
          </Button>
        </PopoverTrigger>
        <PopoverContent
          aria-labelledby={labelId}
          aria-describedby={descriptionId}
          className="flex w-full max-w-[var(--radix-popover-content-available-width,var(--available-width))] origin-[var(--radix-popover-content-transform-origin,var(--transform-origin))] flex-col gap-3.5 p-4 sm:min-w-[380px]"
          {...props}
        >
          <div className="flex flex-col gap-1">
            <div className="flex items-center gap-2">
              <h4 id={labelId} className="leading-none font-medium">
                {sorting.length > 0 ? "Sort by" : "No sorting applied"}
              </h4>
              {sorting.length > 1 && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <CircleHelp className="size-3.5 cursor-help text-muted-foreground" />
                  </TooltipTrigger>
                  <TooltipContent side="right">
                    The order of fields determines sort priority
                  </TooltipContent>
                </Tooltip>
              )}
            </div>
            <p
              id={descriptionId}
              className={cn(
                "text-sm text-muted-foreground",
                sorting.length > 0 && "sr-only",
              )}
            >
              {sorting.length > 0
                ? "Modify sorting to organize your rows."
                : "Add sorting to organize your rows."}
            </p>
          </div>
          {sorting.length > 0 && (
            <SortableContent
              role="list"
              className="flex max-h-[300px] flex-col gap-2 overflow-y-auto p-1"
            >
              {sorting.map(sort => (
                <TableSortItem
                  key={sort.id}
                  sort={sort}
                  menuId={id}
                  columns={columns}
                  columnLabels={columnLabels}
                  onSortUpdate={onSortUpdate}
                  onSortRemove={onSortRemove}
                  getVariantForColumn={getVariantForColumn}
                />
              ))}
            </SortableContent>
          )}
          <div className="flex w-full items-center gap-2">
            {canShowAddSort && (
              <Button
                size="sm"
                className="rounded"
                ref={addButtonRef}
                onClick={onSortAdd}
                disabled={columns.length === 0}
              >
                Add sort
              </Button>
            )}
            {sorting.length > 0 && (
              <Button
                variant="outline"
                size="sm"
                className="rounded"
                onClick={onSortingReset}
              >
                Reset sorting
              </Button>
            )}
          </div>
        </PopoverContent>
      </Popover>
      <SortableOverlay>
        <div className="flex items-center gap-2">
          <div className="h-8 w-[180px] rounded-sm bg-primary/10" />
          <div className="h-8 w-24 rounded-sm bg-primary/10" />
          <div className="size-8 shrink-0 rounded-sm bg-primary/10" />
          <div className="size-8 shrink-0 rounded-sm bg-primary/10" />
        </div>
      </SortableOverlay>
    </Sortable>
  )
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */
TableSortMenu.displayName = "TableSortMenu"

"use client"

/**
 * Niko Table's popover primitive, React Aria build. Radix-shaped API
 * (`Popover open onOpenChange`, `PopoverTrigger asChild`, `PopoverContent
 * align side sideOffset`) on shadcn's React Aria `PopoverTrigger` (React Aria
 * `DialogTrigger`, which owns the open state) and `Popover`.
 *
 * `PopoverTrigger asChild` hands the press to its child: the Button primitive
 * (or shadcn's Button) takes it directly, a plain element through `Pressable`.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
} from "react-aria-components"

import {
  Popover as PopoverPrimitive,
  PopoverTrigger as PopoverRoot,
} from "@/components/ui/popover"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type PressableChild = React.ComponentProps<typeof Pressable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

function useDataState() {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  return isOpen ? "open" : "closed"
}

function Popover({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria popovers are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <PopoverRoot
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </PopoverRoot>
  )
}

function PopoverTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const state = { "data-state": useDataState() }
  // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
  const child =
    asChild && React.isValidElement<object>(children) ? (
      React.cloneElement(children, mergeProps(children.props, props, state))
    ) : (
      <button type="button" {...props} {...state}>
        {children}
      </button>
    )
  // A host element (a plain <button>, <a>) cannot take React Aria's press
  // itself, so Pressable gives it one. A component child (the Button
  // primitive, shadcn's Button) takes it directly; wrapping it too would
  // register the press twice.
  return typeof child.type === "string" ? (
    <Pressable>{child as PressableChild}</Pressable>
  ) : (
    child
  )
}

function PopoverContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  id,
  className,
  children,
  ...props
}: Omit<
  React.ComponentProps<typeof PopoverPrimitive>,
  | "children"
  | "className"
  | "placement"
  | "offset"
  | "crossOffset"
  | "isOpen"
  | "onOpenChange"
  | "triggerRef"
> & {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  /** Radix puts it on the popup; React Aria's popover takes no `id`. */
  id?: string
  className?: string
  children?: React.ReactNode
}) {
  return (
    <PopoverPrimitive
      {...props}
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
      data-state={useDataState()}
    >
      {id ? (
        <div id={id} className="contents">
          {children}
        </div>
      ) : (
        children
      )}
    </PopoverPrimitive>
  )
}

export { Popover, PopoverContent, PopoverTrigger }

"use client"

/**
 * Niko Table's tooltip primitive, React Aria build. Radix-shaped API
 * (`TooltipProvider`, `Tooltip`, `TooltipTrigger asChild`, `TooltipContent
 * side`) on shadcn's React Aria `TooltipTrigger` (which makes the first child
 * focusable) and `Tooltip` popup.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { Placement } from "react-aria-components"

import {
  Tooltip as TooltipPopup,
  TooltipTrigger as TooltipRoot,
} from "@/components/ui/tooltip"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

// React Aria has no provider: the provider's delay feeds each shadcn
// TooltipTrigger's own `delay` prop.
const TooltipDelayContext = React.createContext<number | undefined>(undefined)

/** Radix-shaped provider; it only carries the delay (Radix or Base UI name). */
function TooltipProvider({
  delayDuration,
  delay,
  children,
}: {
  /** Radix name. */
  delayDuration?: number
  /** Base UI name; accepted so a spread of both typechecks. */
  delay?: number
  children?: React.ReactNode
}) {
  return (
    <TooltipDelayContext.Provider value={delayDuration ?? delay}>
      {children}
    </TooltipDelayContext.Provider>
  )
}

function Tooltip({
  open,
  defaultOpen,
  onOpenChange,
  delayDuration,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  delayDuration?: number
  children?: React.ReactNode
}) {
  const providerDelay = React.useContext(TooltipDelayContext)
  return (
    <TooltipRoot
      delay={delayDuration ?? providerDelay}
      closeDelay={0}
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </TooltipRoot>
  )
}

/** Slot: shadcn's TooltipTrigger passes its focus props and ref here. */
function TooltipTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  if (asChild && React.isValidElement<object>(children))
    return React.cloneElement(children, mergeProps(children.props, props))
  return (
    <button type="button" {...props}>
      {children}
    </button>
  )
}

function TooltipContent({
  side = "top",
  align = "center",
  sideOffset = 4,
  alignOffset = 0,
  className,
  children,
}: {
  side?: Side
  align?: Align
  sideOffset?: number
  alignOffset?: number
  className?: string
  children?: React.ReactNode
}) {
  return (
    <TooltipPopup
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
    >
      {children}
    </TooltipPopup>
  )
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger }

"use client"

/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button, buttonVariants }

